(async()=>{const out={};async function render({rate=1,detune=0,offset=0,start=0,stop,duration,sourceRate=8000,loop=false,loopStart=0,loopEnd=0}={}){const c=new OfflineAudioContext(1,12,8000),s=c.createBufferSource(),b=c.createBuffer(1,5,sourceRate);b.getChannelData(0).set([10,20,5,40,50]);s.buffer=b;s.playbackRate.value=rate;s.detune.value=detune;s.loop=loop;s.loopStart=loopStart/sourceRate;s.loopEnd=loopEnd/sourceRate;s.connect(c.destination);s.start(start/8000,offset/sourceRate,duration===undefined?undefined:duration/sourceRate);if(stop!==undefined)s.stop(stop/8000);return Array.from((await c.startRendering()).getChannelData(0))}for(const rate of [0,-1,.5,1.5,2])out['rate'+rate]=await render({rate});for(const offset of [.4,.5,.6,1.5,1.6,5,6])out['offset'+offset]=await render({offset});for(const stop of [.4,.6,1.6])out['stop'+stop]=await render({stop});for(const duration of [.4,.6,1.6,2.5])out['duration'+duration]=await render({duration,rate:.5});out.sourceRate=await render({sourceRate:16000});out.detune=await render({detune:1200});out.loop=await render({rate:.5,loop:true,loopStart:1,loopEnd:4});return out})()
